
document.querySelectorAll('.animated_grid_wrapper').forEach((wrapper) => {
  const rows = parseInt(wrapper.dataset.gridRows) || 10;
  const cols = parseInt(wrapper.dataset.gridCols) || 10;
  const activeColor = wrapper.dataset.gridColor || '#1e90ff';

  const totalCells = rows * cols;

  wrapper.style.gridTemplateColumns = `repeat(${cols},1fr)`;

  const cells = [];

  // 🔥 create grid
  for (let i = 0; i < totalCells; i++) {
    const cell = document.createElement('div');
    cell.classList.add('animated_grid');
    wrapper.appendChild(cell);
    cells.push(cell);
  }

  /* ===========================
     STATIC GRID ANIMATION (SEKALI)
  =========================== */

  const shuffled = gsap.utils.shuffle([...cells]);

  const activeCells = shuffled.slice(0, Math.floor(totalCells * 0.12));

  gsap.fromTo(activeCells,
    {
      backgroundColor: 'transparent',
      boxShadow: '0 0 0px transparent',
    },
    {
      backgroundColor: activeColor,
      boxShadow: `0 0 10px ${activeColor}`,
      duration: 0.8,
      stagger: {
        each: 0.02,
        from: 'random',
      },
      ease: 'power2.out'
    }
  );

  /* ===========================
     METEOR (OPSIONAL: SEKALI)
  =========================== */

  const createMeteorOnce = () => {
    const meteor = document.createElement('div');
    meteor.classList.add('meteor');
    meteor.style.setProperty('--m-color', activeColor);

    const randomCol = Math.floor(Math.random() * cols);
    const xPos = (randomCol / cols) * 100;

    meteor.style.left = `${xPos}%`;
    meteor.style.top = '-150px';

    wrapper.appendChild(meteor);

    gsap.to(meteor, {
      top: '110%',
      opacity: 1,
      duration: 2,
      ease: 'none',
      onComplete: () => meteor.remove(),
    });
  };

  // 🔥 jalankan meteor sekali (optional)
  createMeteorOnce();

});
